def main():
    ap = argparse.ArgumentParser(add_help=True)
    ap.add_argument("--to", default=None, help="目标目录（默认 ~/.workbuddy/skills/bid-quote-cockpit）")
    a = ap.parse_args()
    target = Path(a.to).resolve() if a.to else DEFAULT_TARGET
    print("bid-quote-cockpit %s 安装器" % VERSION)
    print("目标目录: %s" % target)
    if target.exists() and any(target.iterdir()):
        print("注意: 目标已存在内容，同名文件将被覆盖。")
    ok, bad = 0, []
    for rel in sorted(M):
        sha, b64 = M[rel]
        data = base64.b64decode("".join(b64.split()))
        if hashlib.sha256(data).hexdigest() != sha:
            bad.append(rel)
            continue
        dst = target / rel
        dst.parent.mkdir(parents=True, exist_ok=True)
        with open(dst, "wb") as f:
            f.write(data)
        print("  + %-56s %9d B" % (rel, len(data)))
        ok += 1
    if bad:
        print("SHA256 校验失败（未写入）: %s" % bad)
        sys.exit(1)
    print("完成: %d 个文件全部写入并逐文件校验通过。" % ok)
    print("下一步: 确认目录位于技能目录下（默认 ~/.workbuddy/skills/bid-quote-cockpit），重开会话即生效。")


if __name__ == "__main__":
    main()
